const data = $input.first().json.output;
const source = $('Prepare Message').first().json;

const openRequests = source.open_requests || [];
const validationFlags = new Set();

const fieldLabels = {
  subject: "the person who needs access",
  resource: "the resource",
  environment: "the environment",
  permission: "the required permissions",
  duration_hours: "the access duration",
  reason: "the business reason"
};

const fields = Object.keys(fieldLabels);

function isMissing(value) {
  return value === null ||
    value === undefined ||
    (typeof value === "string" && value.trim() === "");
}

function comparable(field, value) {
  if (typeof value !== "string") {
    return value;
  }

  // The model must copy an existing reason without rewriting it.
  if (field === "reason") {
    return value.trim();
  }

  return value.trim().toLowerCase();
}

if (
  data.message_type !== "access_request" &&
  data.requests.length > 0
) {
  validationFlags.add("inconsistent_llm_output");
}

if (
  data.message_type === "access_request" &&
  data.requests.length === 0
) {
  validationFlags.add("empty_access_request");
}

const requests = data.requests.map((candidate) => {
  const request = { ...candidate };

  if (request.target_request_id !== null) {
    const targetId = request.target_request_id.toLowerCase();

    const target = openRequests.find(
      (existing) => existing.id.toLowerCase() === targetId
    );

    const validTarget =
      data.message_type === "access_request" &&
      data.requests.length === 1 &&
      openRequests.length === 1 &&
      target !== undefined &&
      targetId === source.thread_target_request_id;

    if (!validTarget) {
      validationFlags.add("invalid_thread_target");
    } else {
      request.target_request_id = target.id;

      for (const field of fields) {
        const previousValue = target[field];
        const newValue = request[field];

        if (!isMissing(previousValue)) {
          if (
            !isMissing(newValue) &&
            comparable(field, previousValue) !==
              comparable(field, newValue)
          ) {
            validationFlags.add("conflicting_thread_update");
          }

          // Preserve previously known facts deterministically.
          request[field] = previousValue;
        }
      }
    }
  }

  const missingFields = fields.filter(
    (field) => isMissing(request[field])
  );

  return {
    ...request,
    complete: missingFields.length === 0,
    missing_fields: missingFields
  };
});

if (validationFlags.size > 0) {
  return [{
    json: {
      message_type: "ambiguous",
      llm_message_type: data.message_type,
      requests: [],
      message_validation_flags: [...validationFlags],
      clarification_question:
        "Could you clarify whether this is a new request or an update, and which request it refers to?"
    }
  }];
}

const incompleteRequests = requests.filter(
  (request) => !request.complete
);

const details = incompleteRequests.map((request, index) => {
  const label = request.resource || `request ${index + 1}`;

  const missing = request.missing_fields.map(
    (field) => fieldLabels[field]
  );

  return `for ${label}: ${missing.join(", ")}`;
});

let question = null;

if (details.length > 0) {
  question = `Could you clarify ${details.join("; ")}?`;
} else if (data.message_type === "ambiguous") {
  question =
    "Could you clarify what access you need and which request this message refers to?";
}

return [{
  json: {
    message_type: data.message_type,
    llm_message_type: data.message_type,
    requests,
    message_validation_flags: [],
    clarification_question: question
  }
}];

const sourceFlags =
  $('Prepare Message').first().json.security_flags || [];

const policy = {
  grafana: {
    environments: ["development", "staging"],
    permissions: ["viewer"]
  },
  postgres: {
    environments: ["development", "staging"],
    permissions: ["read_only"]
  }
};

return $input.all().map((item) => {
  const data = item.json;

  const messageFlags = [
    ...new Set([
      ...sourceFlags,
      ...(data.message_validation_flags || [])
    ])
  ];

  const llmMessageType =
    data.llm_message_type || data.message_type;

  if (data.message_type !== "access_request") {
    const suspiciousNonRequest =
      data.message_type === "non_request" &&
      messageFlags.length > 0;

    return {
      json: {
        ...data,
        llm_message_type: llmMessageType,
        message_type: suspiciousNonRequest
          ? "ambiguous"
          : data.message_type,
        message_risk_flags: messageFlags,
        message_route:
          data.message_type === "non_request" &&
          messageFlags.length === 0
            ? "ignore"
            : "manual_review"
      }
    };
  }

  const requests = data.requests.map((request) => {
    const resource = request.resource === null
      ? null
      : request.resource.trim().toLowerCase();

    const resourcePolicy =
      Object.prototype.hasOwnProperty.call(policy, resource)
        ? policy[resource]
        : undefined;
    const riskFlags = new Set(messageFlags);

    if (resource !== null && !resourcePolicy) {
      riskFlags.add("unknown_resource");
    }

    if (request.environment === "production") {
      riskFlags.add("production_access");
    }

    if (
      ["write", "admin", "root", "owner"].includes(
        request.permission
      )
    ) {
      riskFlags.add("elevated_permissions");
    }

    if (request.duration_hours > 168) {
      riskFlags.add("duration_exceeds_7_days");
    }

    if (
      resourcePolicy &&
      request.environment !== null &&
      !resourcePolicy.environments.includes(
        request.environment
      )
    ) {
      riskFlags.add("environment_not_allowed");
    }

    if (
      resourcePolicy &&
      request.permission !== null &&
      !resourcePolicy.permissions.includes(
        request.permission
      )
    ) {
      riskFlags.add("permission_not_allowed");
    }

    if (
      request.subject !== null &&
      request.subject !== "self"
    ) {
      riskFlags.add("beneficiary_requires_verification");
    }

    const flags = [...riskFlags];

    const route = flags.length > 0
      ? "manual_review"
      : request.complete
        ? "standard_approval"
        : "needs_clarification";

    return {
      ...request,
      resource,
      risk_flags: flags,
      route
    };
  });

  return {
    json: {
      ...data,
      llm_message_type: llmMessageType,
      message_risk_flags: messageFlags,
      requests,
      message_route: requests.length === 0
        ? "manual_review"
        : null
    }
  };
});

const message = $input.first().json;

if (message.status !== "processing" || !message.lease_token) {
  throw new Error("Queue message is not claimed");
}

const history = message.thread_context || [];
const openRequests = message.open_requests || [];

const securityFlags = new Set(message.security_flags || []);

for (const request of openRequests) {
  for (const flag of request.risk_flags || []) {
    securityFlags.add(flag);
  }
}

if (message.thread_message_count > 10) {
  securityFlags.add("thread_context_truncated");
}

if (openRequests.length > 1) {
  securityFlags.add("multiple_pending_requests");
}

const pendingRequests = openRequests.map((request) => ({
  request_id: request.id,
  subject: request.subject,
  resource: request.resource,
  environment: request.environment,
  permission: request.permission,
  duration_hours: request.duration_hours,
  reason: request.reason,
  missing_fields: request.missing_fields
}));

const llmInput = {
  current_message: {
    author_id: message.author_id,
    text: message.sanitized_text
  },
  pending_requests: pendingRequests,
  previous_messages: history
};

return [{
  json: {
    ...message,
    text: message.sanitized_text,
    security_flags: [...securityFlags],
    thread_target_request_id:
      openRequests.length === 1 ? openRequests[0].id : null,
    llm_input: JSON.stringify(llmInput)
  }
}];
